INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine starre Hierarchie hier entscheidend?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibilität im Fokus"}, {"text": "Ja", "correct": false, "because": "Teamorientierung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beschreibt diese Struktur am besten?', 3, '[{"text": "Anpassungsfähigkeit", "correct": true, "because": "Schnelle Reaktion möglich"}, {"text": "Feste Befehlskette", "correct": false, "because": "Flexibel organisiert"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Teamautonomie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet mir diese Organisation?', 5, '[{"text": "Schnelle Anpassung", "correct": true, "because": "Flexibel auf Änderungen"}, {"text": "Teamzusammenarbeit", "correct": true, "because": "Kooperation gefördert"}, {"text": "Strikte Kontrolle", "correct": false, "because": "Autonomie im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Teams sind selbstorganisiert. b) Planung ist starr.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Planung flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich in dieser Struktur?', 4, '[{"text": "Teamautonomie", "correct": false, "because": "Kern der Organisation"}, {"text": "Flexibilität", "correct": false, "because": "Grundprinzip"}, {"text": "Feste Hierarchie", "correct": true, "because": "Weniger wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob diese Struktur für große Firmen passt?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierbar mit Teams"}, {"text": "Nein", "correct": false, "because": "Größe kein Hindernis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Zusammenarbeit hier?', 3, '[{"text": "Zentrales Element", "correct": true, "because": "Teamorientiert"}, {"text": "Nebensache", "correct": false, "because": "Kooperation essenziell"}, {"text": "Optional", "correct": false, "because": "Grundprinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente prägen diese Organisation?', 5, '[{"text": "Selbstorganisierte Teams", "correct": true, "because": "Autonomie fördern"}, {"text": "Flexible Prozesse", "correct": true, "because": "Schnelle Anpassung"}, {"text": "Zentrale Vorgaben", "correct": false, "because": "Dezentralisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Teams entscheiden selbst. b) Alles ist zentral geregelt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zentralität fehlt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Teamkoordination", "correct": false, "because": "Erfolgsschlüssel"}, {"text": "Flexibilität", "correct": false, "because": "Kernprinzip"}, {"text": "Strikte Vorgaben", "correct": true, "because": "Autonomie im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist diese Struktur immer chaotisch?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur durch Teams"}, {"text": "Ja", "correct": false, "because": "Organisiert flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördern den Erfolg hier?', 4, '[{"text": "Schnelle Reaktion", "correct": true, "because": "Anpassung an Veränderung"}, {"text": "Teamverantwortung", "correct": true, "because": "Selbstorganisation"}, {"text": "Feste Strukturen", "correct": false, "because": "Flexibilität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hier niemand entscheidet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Teams treffen Entscheidungen"}, {"text": "Ja", "correct": false, "because": "Selbstorganisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in dieser Organisation?', 3, '[{"text": "Teamautonomie", "correct": true, "because": "Fördert Eigenverantwortung"}, {"text": "Zentrale Kontrolle", "correct": false, "because": "Wenig Einfluss"}, {"text": "Feste Pläne", "correct": false, "because": "Flexibilität nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Flexibilität ist zentral. b) Teams brauchen strikte Regeln.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Regeln minimal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile könnten auftreten?', 5, '[{"text": "Koordinationsaufwand", "correct": true, "because": "Teams abstimmen"}, {"text": "Unklare Verantwortung", "correct": true, "because": "Autonomie komplex"}, {"text": "Zu viel Zentralität", "correct": false, "because": "Dezentralisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Teamzusammenarbeit", "correct": false, "because": "Kern der Struktur"}, {"text": "Anpassungsfähigkeit", "correct": false, "because": "Grundprinzip"}, {"text": "Zentrale Hierarchie", "correct": true, "because": "Teams im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert diese Struktur starre Prozesse?', 3, '[{"text": "Nein", "correct": true, "because": "Flexibilität im Vordergrund"}, {"text": "Ja", "correct": false, "because": "Prozesse anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob diese Struktur für kleine Projekte geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel skalierbar"}, {"text": "Nein", "correct": false, "because": "Größe kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für schnelle Änderungen?', 4, '[{"text": "Teamentscheidungen", "correct": true, "because": "Autonomie nutzen"}, {"text": "Zentrale Anweisung", "correct": false, "because": "Langsamer"}, {"text": "Feste Regeln", "correct": false, "because": "Flexibilität zählt"}]');
